      en: ["A mountain range in south-central Hokkaido known for its steep, rugged peaks shaped by glaciers.", "Located within the island nation of Japan in the North Pacific.", "Plays a role in the local identity of the region.", "Known for its scenic or cultural significance."],
      es: ["Una cordillera en el centro-sur de Hokkaido, conocida por sus picos escarpados y dentados formados por glaciares.", "Se encuentra en el territorio del estado insular de Japón, en el Pacífico Norte.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Uma cadeia de montanhas no centro-sul de Hokkaido, conhecida por seus picos íngremes e recortados formados por geleiras.", "Localiza-se no território do estado insular do Japão, no Pacífico Norte.", "Desempenha um papel na identidade local da região.", "Conhecido por sua importância paisagística ou cultural."],
      fr: ["Une chaîne de montagnes dans le centre-sud de Hokkaido, connue pour ses sommets escarpés et déchiquetés façonnés par les glaciers.", "Situé sur le territoire de l'État insulaire du Japon, dans le Pacifique Nord.", "Joue un rôle dans l'identité locale de la région.", "Reconnu pour son importance paysagère ou culturelle."],
