      ro: ["Un vulcan complex la granița dintre prefecturile Yamagata și Miyagi, renumit pentru 'monștrii de zăpadă' din timpul iernii și pentru lacul crater Okama.", "Se află pe teritoriul statului insular Japonia, în Pacificul de Nord.", "Are un rol în identitatea locală a regiunii.", "Este cunoscut pentru semnificația sa peisagistică sau culturală."],
      en: ["A complex volcano on the border of Yamagata and Miyagi Prefectures, famous for its 'snow monsters' in winter and the Okama Crater Lake.", "Located within the island nation of Japan in the North Pacific.", "Plays a role in the local identity of the region.", "Known for its scenic or cultural significance."],
      es: ["Un volcán complejo en el límite entre las prefecturas de Yamagata y Miyagi, famoso por sus 'monstruos de nieve' en invierno y el lago de cráter Okama.", "Situado en el territorio de la nación insular de Japón en el Pacífico Norte.", "Desempeña un papel en la identidad local de la región.", "Conocido por su importancia paisajística o cultural."],
      pt: ["Um vulcão complexo na fronteira entre as províncias de Yamagata e Miyagi, famoso pelos seus 'monstros de neve' no inverno e o lago de cratera Okama.", "Situado no território do arquipélago do Japão, no Pacífico Norte.", "Desempenha um papel na identidade local da região.", "Conhecido pela sua importância paisagística ou cultural."],
      fr: ["Un volcan complexe à la limite des préfectures de Yamagata et Miyagi, célèbre pour ses 'monstres de neige' en hiver et le lac de cratère Okama.", "Situé sur le territoire de l'État insulaire du Japon dans le Pacifique Nord.", "Joue un rôle dans l'identité locale de la région.", "Connu pour son importance paysagère ou culturelle."],
